final class DocumentsModule
{
    public function __construct(
        private readonly DocumentsClient $client,
        private readonly LoansClient $loans,
        private readonly string $bearer,
        private readonly array $identity,
    ){}

    public function handle(string $path,string $method):bool
    {
        if($path==='/documents'){ $this->overview();return true; }
        if(preg_match('#^/loans/requests/([a-f0-9]{26})/documents$#',$path,$m)){ $method==='POST'?$this->uploadToLoan($m[1]):$this->loanDocuments($m[1]);return true; }
        if(preg_match('#^/loans/requests/([a-f0-9]{26})/guarantors/([a-f0-9]{26})/documents$#',$path,$m)&&$method==='POST'){ $this->uploadToGuarantor($m[1],$m[2]);return true; }
        if(preg_match('#^/documents/files/([a-f0-9]{26})$#',$path,$m)&&$method==='GET'){ $this->detail($m[1]);return true; }
        if(preg_match('#^/documents/files/([a-f0-9]{26})/replace$#',$path,$m)&&$method==='POST'){ $this->replace($m[1]);return true; }
        if(preg_match('#^/documents/files/([a-f0-9]{26})/review$#',$path,$m)&&$method==='POST'){ $this->review($m[1]);return true; }
        if(preg_match('#^/documents/files/([a-f0-9]{26})/archive$#',$path,$m)&&$method==='POST'){ $this->archive($m[1]);return true; }
        if(preg_match('#^/documents/files/([a-f0-9]{26})/(download|preview)$#',$path,$m)&&$method==='GET'){ $this->openFile($m[1],$m[2]);return true; }
        return false;
    }

    private function overview():void
    {
        $stats=$this->client->get('/api/v1/stats',$this->bearer);$s=$stats->ok()&&is_array($stats->json['data']??null)?$stats->json['data']:[];
        $content=$this->head('مدارک','مدیریت متمرکز فایل‌های پرونده، نسخه‌ها، بازبینی و دسترسی امن.').$this->takeFlash();
        if(!$stats->ok())$content.=$this->alert('error','سرویس مدارک در دسترس نیست',$this->apiMessage($stats));
        $content.='<div class="bn-stats">'.$this->stat('مدارک فعال',$s['active_documents']??'—','فایل ثبت‌شده').$this->stat('در انتظار بررسی',$s['pending_review']??'—','نیازمند اقدام').$this->stat('تأیید شده',$s['approved']??'—','بازبینی موفق',true).$this->stat('رد شده',$s['rejected']??'—','نیازمند جایگزینی').'</div>';
        $requestList=$this->requestListPath();$content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۱</span><div><h2 class="bn-sectiontitle">مدارک پرونده‌های تسهیلات</h2><p class="bn-sectiondesc">برای بارگذاری و بررسی مدارک، ابتدا پرونده تسهیلات مربوط را باز کنید.</p></div></div><div class="bn-action-grid"><a class="bn-action-card" href="'.Renderer::e($requestList).'"><strong>پرونده‌های تسهیلات</strong><span>انتخاب پرونده و مشاهده چک‌لیست مدارک الزامی نسخه طرح.</span></a></div></section>';
        if($this->can('documents.manage')){
            $page=max(1,(int)($_GET['page']??1));$q=trim((string)($_GET['q']??''));$review=trim((string)($_GET['review_status']??''));$category=trim((string)($_GET['category']??''));$recordStatus=strtolower(trim((string)($_GET['status']??'active')));if(!in_array($recordStatus,['active','archived','all'],true))$recordStatus='active';
            $catR=$this->client->get('/api/v1/categories',$this->bearer);$categoryOptions=[];if($catR->ok()){foreach((array)($catR->json['data']['items']??[]) as$c){if(!is_array($c))continue;$code=(string)($c['category']??'');if($code==='')continue;$categoryOptions[$code]=$this->categoryLabel($code);}}$categoryOptions=array_unique($categoryOptions);ksort($categoryOptions,SORT_STRING);
            $r=$this->client->get('/api/v1/documents',$this->bearer,['page'=>$page,'per_page'=>20,'q'=>$q,'review_status'=>$review,'category'=>$category,'status'=>$recordStatus]);
