                if($rows==='')$rows='<tr><td colspan="6"><div class="bn-empty-inline"><strong>مدرکی با این فیلتر پیدا نشد</strong><span>فیلترها را تغییر دهید یا پس از ثبت مدارک دوباره بررسی کنید.</span></div></td></tr>';
                $catOptions='<option value="">همه دسته‌ها</option>';foreach($categoryOptions as$code=>$label)$catOptions.=$this->option((string)$code,(string)$label,$category);
                $content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۲</span><div><h2 class="bn-sectiontitle">فهرست مدیریتی مدارک</h2><p class="bn-sectiondesc">جستجو، فیلتر وضعیت و مشاهده رکوردهای فعال یا بایگانی‌شده.</p></div></div><form class="bn-filterbar bn-filterbar--documents" method="get" action="/documents"><div class="bn-field bn-field--grow"><label class="bn-label">جستجو</label><input name="q" value="'.Renderer::e($q).'" placeholder="نام فایل، عنوان مدرک یا شناسه پرونده"></div><div class="bn-field"><label class="bn-label">دسته مدرک</label><select name="category">'.$catOptions.'</select></div><div class="bn-field"><label class="bn-label">بازبینی</label><select name="review_status"><option value="">همه وضعیت‌ها</option>'.$this->option('pending','در انتظار',$review).$this->option('approved','تأیید شده',$review).$this->option('rejected','رد شده',$review).'</select></div><div class="bn-field"><label class="bn-label">رکورد</label><select name="status">'.$this->option('active','فعال',$recordStatus).$this->option('archived','بایگانی',$recordStatus).$this->option('all','همه',$recordStatus).'</select></div><div class="bn-filter-actions"><button class="bn-btn bn-btn--primary" type="submit">اعمال فیلتر</button><a class="bn-btn bn-btn--secondary" href="/documents">پاک‌کردن</a></div></form><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>مدرک</th><th>دسته</th><th>بازبینی</th><th>رکورد</th><th>حجم</th><th>آخرین تغییر</th></tr></thead><tbody>'.$rows.'</tbody></table></div>'.$this->pagination('/documents',(int)($data['page']??$page),(int)($data['per_page']??20),(int)($data['total']??count($items)),['q'=>$q,'review_status'=>$review,'category'=>$category,'status'=>$recordStatus]).'</section>';
            }else{$content.=$this->alert('error','فهرست مدارک دریافت نشد',$this->apiMessage($r));}
        }
        echo Renderer::page('مدارک',$content,$this->identity,'documents');
    }

    private function loanDocuments(string$id):void
