        $loanR=$this->loans->get('/api/v1/requests/'.$id,$this->bearer);if(!$loanR->ok()){$this->errorPage('مدارک پرونده',$loanR);return;}$loan=is_array($loanR->json['data']['request']??null)?$loanR->json['data']['request']:[];
        $listR=$this->client->get('/api/v1/entities/loan_request/'.$id.'/documents',$this->bearer);$completionR=$this->client->get('/api/v1/entities/loan_request/'.$id.'/completion',$this->bearer);$catR=$this->client->get('/api/v1/categories',$this->bearer);
        if(!$listR->ok()||!$completionR->ok()||!$catR->ok()){$bad=!$listR->ok()?$listR:(!$completionR->ok()?$completionR:$catR);$this->errorPage('مدارک پرونده',$bad);return;}
        $docs=is_array($listR->json['data']['items']??null)?$listR->json['data']['items']:[];$completion=is_array($completionR->json['data']??null)?$completionR->json['data']:[];$cats=is_array($catR->json['data']['items']??null)?$catR->json['data']['items']:[];
        $catalog=[];foreach($cats as$c)if(is_array($c)&&is_string($c['code']??null))$catalog[(string)$c['code']]=(string)($c['label']??$c['code']);
        $guarantorSections='';$guarantorCompletion=is_array($completion['guarantors']??null)?$completion['guarantors']:[];
        $guarantorCatalog=array_filter($catalog,static fn($label,$code):bool=>str_starts_with((string)$code,'guarantor_'),ARRAY_FILTER_USE_BOTH);
        foreach($guarantorCompletion as$gc){if(!is_array($gc))continue;$gid=(string)($gc['guarantor_id']??'');if($gid==='')continue;$gName=(string)($gc['full_name']??'ضامن');$gDocsR=$this->client->get('/api/v1/entities/loan_guarantor/'.$gid.'/documents',$this->bearer);$gDocs=$gDocsR->ok()&&is_array($gDocsR->json['data']['items']??null)?$gDocsR->json['data']['items']:[];
            $gCheck='';foreach((array)($gc['items']??[]) as$item){if(!is_array($item))continue;$code=(string)($item['document_type']??'');$state=(string)($item['review_status']??'missing');$gCheck.='<div class="bn-document-check '.($state==='approved'?'is-complete':($state==='rejected'?'is-rejected':'')).'"><span class="bn-document-check-icon">'.($state==='approved'?Renderer::icon('check'):($state==='rejected'?Renderer::icon('circle-exclamation'):Renderer::icon('clock-rotate-left'))).'</span><span><strong>'.Renderer::e($catalog[$code]??$code).'</strong><small>'.$this->reviewLabel($state).'</small></span></div>';}
            if($gCheck==='')$gCheck='<div class="bn-empty-inline">برای این ضامن مدرک الزامی تعریف نشده است.</div>';
            $gRows='';foreach($gDocs as$d){if(!is_array($d))continue;$did=(string)$d['id'];$gRows.='<tr><td><a class="bn-table-link" href="/documents/files/'.Renderer::e($did).'"><strong>'.Renderer::e((string)($d['label']??'مدرک')).'</strong><small>'.Renderer::e((string)($d['original_name']??'')).'</small></a></td><td>'.$this->reviewBadge((string)($d['review_status']??'pending')).'</td><td>'.Renderer::e($this->fileSize((int)($d['size_bytes']??0))).'</td></tr>';}
            if($gRows==='')$gRows='<tr><td colspan="3"><div class="bn-empty-inline">هنوز مدرکی برای این ضامن ثبت نشده است.</div></td></tr>';
            $gUpload='';if($this->can('documents.upload')&&$guarantorCatalog!==[]){$opts='<option value="">انتخاب کنید</option>';foreach($guarantorCatalog as$code=>$label)$opts.='<option value="'.Renderer::e((string)$code).'">'.Renderer::e((string)$label).'</option>';$gUpload='<form method="post" enctype="multipart/form-data" action="/loans/requests/'.$id.'/guarantors/'.$gid.'/documents" data-submit-lock="1"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><div class="bn-grid bn-grid--2"><div class="bn-field"><label class="bn-label">نوع مدرک ضامن</label><select name="document_type" required>'.$opts.'</select></div><div class="bn-field"><label class="bn-label">فایل</label><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp,.pdf" required></div></div><div class="bn-form-actions"><button class="bn-btn bn-btn--primary bn-btn--small" type="submit">بارگذاری مدرک ضامن</button></div></form>';}
            $guarantorSections.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">ض</span><div><h2 class="bn-sectiontitle">مدارک '.Renderer::e($gName).'</h2><p class="bn-sectiondesc">مدارک این ضامن با شناسه مستقل به پرونده متصل می‌شوند.</p></div></div><div class="bn-document-checklist">'.$gCheck.'</div><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>مدرک</th><th>وضعیت</th><th>حجم</th></tr></thead><tbody>'.$gRows.'</tbody></table></div>'.$gUpload.'</section>';
        }
        $items=is_array($completion['items']??null)?$completion['items']:[];$check='';foreach($items as$item){if(!is_array($item))continue;$code=(string)($item['document_type']??'');$state=(string)($item['review_status']??'missing');$check.='<div class="bn-document-check '.($state==='approved'?'is-complete':($state==='rejected'?'is-rejected':'')).'"><span class="bn-document-check-icon">'.($state==='approved'?Renderer::icon('check'):($state==='rejected'?Renderer::icon('circle-exclamation'):Renderer::icon('clock-rotate-left'))).'</span><span><strong>'.Renderer::e($catalog[$code]??$code).'</strong><small>'.$this->reviewLabel($state).'</small></span></div>';}
