        $rows='';foreach($docs as$d){if(!is_array($d))continue;$did=(string)$d['id'];$rows.='<tr><td><a class="bn-table-link" href="/documents/files/'.Renderer::e($did).'"><strong>'.Renderer::e((string)($d['label']??'مدرک')).'</strong><small>'.Renderer::e((string)($d['original_name']??'')).'</small></a></td><td>'.$this->reviewBadge((string)($d['review_status']??'pending')).'</td><td>نسخه '.Renderer::e(PersianDateTime::digits((string)($d['current_version']??1))).'</td><td>'.Renderer::e($this->fileSize((int)($d['size_bytes']??0))).'</td><td><div class="bn-row-actions"><a class="bn-btn bn-btn--small bn-btn--secondary" href="/documents/files/'.Renderer::e($did).'/preview">پیش‌نمایش</a><a class="bn-btn bn-btn--small bn-btn--ghost" href="/documents/files/'.Renderer::e($did).'/download">دانلود</a></div></td></tr>';}
        if($rows==='')$rows='<tr><td colspan="5"><div class="bn-empty-inline"><strong>هنوز مدرکی بارگذاری نشده</strong><span>از فرم پایین، اولین مدرک پرونده را ثبت کنید.</span></div></td></tr>';
        $req=is_array($completion['requirements']??null)?$completion['requirements']:[];$complete=($completion['complete']??false)===true;
