        $content.='<div class="bn-document-summary '.($complete?'is-complete':'').'"><div><span class="bn-document-summary-mark">'.($complete?Renderer::icon('check'):Renderer::icon('circle-exclamation')).'</span><div><strong>'.($complete?'مدارک الزامی تکمیل و تأیید شده‌اند':'پرونده هنوز از نظر مدارک کامل نیست').'</strong><p>'.($complete?'گردش‌کار می‌تواند وارد مرحله تأیید مدارک شود.':'همه مدارک الزامی باید بارگذاری و تأیید شوند.').'</p></div></div><span class="bn-status '.($complete?'bn-status--ok':'bn-status--warn').'">'.($complete?'کامل':'نیازمند اقدام').'</span></div>';
        $content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۱</span><div><h2 class="bn-sectiontitle">چک‌لیست مدارک الزامی</h2><p class="bn-sectiondesc">این فهرست از نسخه پین‌شده طرح همین پرونده خوانده می‌شود.</p></div></div><div class="bn-document-checklist">'.$check.'</div></section>';
        $content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۲</span><div><h2 class="bn-sectiontitle">مدارک ثبت‌شده</h2><p class="bn-sectiondesc">نسخه جاری، وضعیت بازبینی و عملیات امن هر فایل.</p></div></div><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>مدرک</th><th>وضعیت</th><th>نسخه</th><th>حجم</th><th>عملیات</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>';
