    private function uploadToLoan(string$id):void
    {
        $return='/loans/requests/'.$id.'/documents';if(IniSize::requestExceedsPostLimit()){$this->flash('error','حجم درخواست از محدودیت بارگذاری PHP پنل بیشتر است. اندازه فایل را کاهش دهید یا post_max_size هاست را افزایش دهید.');$this->redirect($return);}if(!$this->csrf($return))return;$file=is_array($_FILES['file']??null)?$_FILES['file']:[];if($file===[]||((int)($file['error']??UPLOAD_ERR_NO_FILE))===UPLOAD_ERR_NO_FILE){$this->flash('error','فایل مدرک دریافت نشد. فایل را دوباره انتخاب کنید.');$this->redirect($return);}$fields=['document_type'=>(string)($_POST['document_type']??'')];$r=$this->client->upload('loan_request',$id,$this->bearer,$file,$fields);$this->flash($r->ok()?'success':'error',$r->ok()?'مدرک با موفقیت و به‌صورت امن ثبت شد.':$this->apiMessage($r));$this->redirect($return);
    }

    private function uploadToGuarantor(string$requestId,string$guarantorId):void
    {
        $return='/loans/requests/'.$requestId.'/documents';if(IniSize::requestExceedsPostLimit()){$this->flash('error','حجم درخواست از محدودیت بارگذاری PHP پنل بیشتر است.');$this->redirect($return);}if(!$this->csrf($return))return;$file=is_array($_FILES['file']??null)?$_FILES['file']:[];if($file===[]||((int)($file['error']??UPLOAD_ERR_NO_FILE))===UPLOAD_ERR_NO_FILE){$this->flash('error','فایل مدرک ضامن دریافت نشد.');$this->redirect($return);}$fields=['document_type'=>(string)($_POST['document_type']??'')];$r=$this->client->upload('loan_guarantor',$guarantorId,$this->bearer,$file,$fields);$this->flash($r->ok()?'success':'error',$r->ok()?'مدرک ضامن با موفقیت ثبت شد.':$this->apiMessage($r));$this->redirect($return);
    }

    private function detail(string$id):void
    {
        $r=$this->client->get('/api/v1/files/'.$id,$this->bearer);if(!$r->ok()){$this->errorPage('جزئیات مدرک',$r);return;}$doc=is_array($r->json['data']['document']??null)?$r->json['data']['document']:[];$versions=is_array($doc['versions']??null)?$doc['versions']:[];$auditR=$this->can('documents.audit')?$this->client->get('/api/v1/files/'.$id.'/audit',$this->bearer):null;$reviews=$auditR&&$auditR->ok()&&is_array($auditR->json['data']['reviews']??null)?$auditR->json['data']['reviews']:[];$audits=$auditR&&$auditR->ok()&&is_array($auditR->json['data']['audit']??null)?$auditR->json['data']['audit']:[];
        $content=$this->head((string)($doc['label']??'جزئیات مدرک'),'نسخه‌ها، وضعیت بازبینی و سوابق دسترسی این مدرک.','<a class="bn-btn bn-btn--secondary" href="/documents">بازگشت به مدارک</a>').$this->takeFlash();
        $content.='<div class="bn-detail-grid">'.$this->detailItem('نام فایل',(string)($doc['original_name']??'—')).$this->detailItem('نوع فایل',(string)($doc['mime_type']??'—')).$this->detailItem('حجم',$this->fileSize((int)($doc['size_bytes']??0))).$this->detailItem('نسخه جاری','نسخه '.PersianDateTime::digits((string)($doc['current_version']??1))).$this->detailItem('وضعیت بازبینی',$this->reviewLabel((string)($doc['review_status']??'pending'))).$this->detailItem('محرمانگی',(string)($doc['visibility']??'normal')==='confidential'?'محرمانه':'عادی').'</div>';
        $vrows='';foreach($versions as$v){if(!is_array($v))continue;$vid=(string)($v['id']??'');$vrows.='<tr><td>نسخه '.Renderer::e(PersianDateTime::digits((string)($v['version']??''))).'</td><td>'.Renderer::e((string)($v['original_name']??'')).'</td><td>'.Renderer::e($this->fileSize((int)($v['size_bytes']??0))).'</td><td>'.Renderer::e(PersianDateTime::fromIso((string)($v['uploaded_at']??''),false)??'—').'</td><td><a class="bn-btn bn-btn--small bn-btn--ghost" href="/documents/files/'.$id.'/download?version_id='.rawurlencode($vid).'">دانلود</a></td></tr>';}
        $content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۱</span><div><h2 class="bn-sectiontitle">تاریخچه نسخه‌ها</h2><p class="bn-sectiondesc">جایگزینی فایل، نسخه قبلی را حذف نمی‌کند.</p></div></div><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>نسخه</th><th>نام فایل</th><th>حجم</th><th>زمان ثبت</th><th>عملیات</th></tr></thead><tbody>'.$vrows.'</tbody></table></div></section>';
        if($this->can('documents.replace')&&($doc['status']??'active')==='active')$content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۲</span><div><h2 class="bn-sectiontitle">جایگزینی نسخه</h2><p class="bn-sectiondesc">فایل جدید به‌عنوان نسخه بعدی ثبت می‌شود و وضعیت بازبینی به «در انتظار» برمی‌گردد.</p></div></div><form method="post" enctype="multipart/form-data" action="/documents/files/'.$id.'/replace" data-submit-lock="1"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><input type="hidden" name="return_to" value="/documents/files/'.$id.'"><label class="bn-upload-box"><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp,.pdf" required data-file-input data-max-bytes="'.Renderer::e((string)IniSize::effectiveUploadLimit(10485760)).'"><span class="bn-upload-icon">↻</span><span><strong>انتخاب نسخه جدید</strong><small data-file-name>فایل انتخاب نشده است</small></span></label><small class="bn-file-error" data-file-error hidden></small><div class="bn-form-actions"><button class="bn-btn bn-btn--primary" type="submit">ثبت نسخه جدید</button></div></form></section>';
        if($this->can('documents.review')&&($doc['status']??'active')==='active')$content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۳</span><div><h2 class="bn-sectiontitle">بازبینی مدرک</h2><p class="bn-sectiondesc">برای رد مدرک، ثبت علت الزامی است.</p></div></div><form method="post" action="/documents/files/'.$id.'/review" data-document-review><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><input type="hidden" name="return_to" value="/documents/files/'.$id.'"><div class="bn-grid bn-grid--2"><div class="bn-field"><label class="bn-label">نتیجه بازبینی</label><select name="status" required data-review-status><option value="approved">تأیید مدرک</option><option value="rejected">رد مدرک</option></select></div><div class="bn-field bn-grid-span-2"><label class="bn-label">دلیل / توضیح</label><textarea name="reason" rows="3" data-review-reason placeholder="برای رد مدرک، علت را دقیق ثبت کنید"></textarea></div></div><div class="bn-form-actions"><button class="bn-btn bn-btn--primary" type="submit">ثبت نتیجه بازبینی</button></div></form></section>';
        if($reviews!==[]||$audits!==[]){$events='';foreach(array_slice($audits,0,30) as$a){if(!is_array($a))continue;$events.='<div class="bn-event-item"><span class="bn-event-dot"></span><div><strong>'.Renderer::e($this->eventLabel((string)($a['event_type']??''))).'</strong><p>'.Renderer::e(PersianDateTime::fromIso((string)($a['created_at']??''),true)??'—').'</p></div><span class="bn-status '.((string)($a['result']??'allowed')==='allowed'?'bn-status--ok':'bn-status--bad').'">'.((string)($a['result']??'allowed')==='allowed'?'مجاز':'رد شده').'</span></div>';}$content.='<section class="bn-section"><div class="bn-sectionhead"><span class="bn-step">۴</span><div><h2 class="bn-sectiontitle">ردپای عملیاتی</h2><p class="bn-sectiondesc">رویدادهای مهم این مدرک برای پیگیری ثبت می‌شوند.</p></div></div><div class="bn-event-list">'.$events.'</div></section>';}
        if($this->can('documents.archive')&&($doc['status']??'active')==='active')$content.='<section class="bn-section bn-section--soft"><div class="bn-sectionhead"><span class="bn-step">۵</span><div><h2 class="bn-sectiontitle">بایگانی مدرک</h2><p class="bn-sectiondesc">فایل فیزیکی حذف نمی‌شود و سابقه آن برای Audit باقی می‌ماند.</p></div></div><form method="post" action="/documents/files/'.$id.'/archive" data-submit-lock="1"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><input type="hidden" name="return_to" value="/documents"><div class="bn-field"><label class="bn-label">دلیل بایگانی <span class="bn-required">*</span></label><textarea name="reason" rows="3" required></textarea></div><div class="bn-form-actions"><button class="bn-btn bn-btn--danger" type="submit">بایگانی مدرک</button></div></form></section>';
        echo Renderer::page('جزئیات مدرک',$content,$this->identity,'documents');
    }

    private function replace(string$id):void{$return=$this->returnTo('/documents/files/'.$id);if(IniSize::requestExceedsPostLimit()){$this->flash('error','حجم نسخه جدید از محدودیت بارگذاری PHP پنل بیشتر است.');$this->redirect($return);}if(!$this->csrf($return))return;$file=is_array($_FILES['file']??null)?$_FILES['file']:[];if($file===[]||((int)($file['error']??UPLOAD_ERR_NO_FILE))===UPLOAD_ERR_NO_FILE){$this->flash('error','فایل نسخه جدید دریافت نشد.');$this->redirect($return);}$r=$this->client->replace($id,$this->bearer,$file);$this->flash($r->ok()?'success':'error',$r->ok()?'نسخه جدید با موفقیت ثبت شد.':$this->apiMessage($r));$this->redirect($return);}
    private function review(string$id):void{if(!$this->csrf($this->returnTo('/documents/files/'.$id)))return;$status=(string)($_POST['status']??'');$reason=trim((string)($_POST['reason']??''));$r=$this->client->post('/api/v1/files/'.$id.'/review',$this->bearer,['status'=>$status,'reason'=>$reason]);$this->flash($r->ok()?'success':'error',$r->ok()?'نتیجه بازبینی ثبت شد.':$this->apiMessage($r));$this->redirect($this->returnTo('/documents/files/'.$id));}
    private function archive(string$id):void{if(!$this->csrf($this->returnTo('/documents')))return;$r=$this->client->post('/api/v1/files/'.$id.'/archive',$this->bearer,['reason'=>trim((string)($_POST['reason']??''))]);$this->flash($r->ok()?'success':'error',$r->ok()?'مدرک بایگانی شد و سابقه آن حفظ شد.':$this->apiMessage($r));$this->redirect($this->returnTo('/documents'));}

    private function openFile(string$id,string$purpose):void
    {
        $version=trim((string)($_GET['version_id']??''));$payload=['purpose'=>$purpose];if($version!=='')$payload['version_id']=$version;$r=$this->client->post('/api/v1/files/'.$id.'/access-token',$this->bearer,$payload);if(!$r->ok()){$this->errorPage($purpose==='preview'?'پیش‌نمایش مدرک':'دانلود مدرک',$r);return;}$path=(string)($r->json['data']['path']??'');if(!str_starts_with($path,'/api/v1/access/')){$this->errorPage('دسترسی به فایل',new HttpResponse(502,['error'=>['message'=>'پاسخ لینک امن معتبر نیست.']]));return;}header('Referrer-Policy: no-referrer');header('Location: '.$this->client->absolute($path),true,303);exit;
    }

    private function requestListPath():string
    {
        $roles=is_array($this->identity['roles']??null)?$this->identity['roles']:[];
        if(in_array('applicant',$roles,true)&&!in_array('super_admin',$roles,true)&&!in_array('admin',$roles,true))return '/applicant/requests';
        if(in_array('acceptor',$roles,true)&&!in_array('super_admin',$roles,true)&&!in_array('admin',$roles,true))return '/acceptor/requests';
        return '/loans/requests';
    }
    private function requestDetailPath(string$id):string{return rtrim($this->requestListPath(),'/').'/'.$id;}

    private function can(string$permission):bool{$roles=is_array($this->identity['roles']??null)?$this->identity['roles']:[];$p=is_array($this->identity['permissions']??null)?$this->identity['permissions']:[];return in_array('super_admin',$roles,true)||in_array($permission,$p,true);}
    private function csrf(string$return):bool{if(Csrf::valid((string)($_POST['_csrf']??'')))return true;$this->flash('error','اعتبار فرم منقضی شده است. صفحه را تازه‌سازی کنید.');$this->redirect($return);return false;}
    private function returnTo(string$fallback):string{$v=(string)($_POST['return_to']??$fallback);return preg_match('#^/(?:documents(?:/files/[a-f0-9]{26})?|loans/requests/[a-f0-9]{26}/documents)$#',$v)?$v:$fallback;}
    private function redirect(string$path):never{header('Location: '.$path,true,303);exit;}
    private function head(string$title,string$subtitle,string$actions=''):string{return'<div class="bn-pagehead"><div class="bn-pagehead-main"><div class="bn-eyebrow">مدیریت مدارک</div><h1 class="bn-title">'.Renderer::e($title).'</h1><p class="bn-subtitle">'.Renderer::e($subtitle).'</p></div>'.($actions!==''?'<div class="bn-actions">'.$actions.'</div>':'').'</div>';}
    private function stat(string$label,mixed$value,string$caption,bool$accent=false):string{return'<div class="bn-stat'.($accent?' bn-stat--accent':'').'"><div class="bn-stat-label">'.Renderer::e($label).'</div><div class="bn-stat-value">'.Renderer::e(PersianDateTime::digits((string)$value)).'</div><div class="bn-stat-caption">'.Renderer::e($caption).'</div></div>';}
    private function detailItem(string$label,string$value):string{return'<div class="bn-detail-item"><span>'.Renderer::e($label).'</span><strong>'.Renderer::e($value).'</strong></div>';}
    private function reviewBadge(string$status):string{$class=$status==='approved'?'bn-status--ok':($status==='rejected'?'bn-status--bad':'bn-status--warn');return'<span class="bn-status '.$class.'">'.Renderer::e($this->reviewLabel($status)).'</span>';}
    private function reviewLabel(string$status):string{return['approved'=>'تأیید شده','rejected'=>'رد شده','pending'=>'در انتظار بررسی','missing'=>'بارگذاری نشده'][$status]??$status;}
    private function categoryLabel(string$c):string{return['identity'=>'هویتی','employment'=>'شغلی','financial'=>'مالی','check_primary'=>'چک اصلی','check_secondary'=>'چک تکمیلی','guarantor'=>'ضامن','credit_check'=>'اعتبارسنجی','contract'=>'قرارداد','invoice'=>'فاکتور','supplemental'=>'تکمیلی','case_receipt'=>'رسید پرونده','settlement_receipt'=>'رسید تسویه'][$c]??$c;}
    private function fileSize(int$bytes):string{if($bytes<=0)return'۰ بایت';if($bytes>=1048576)return PersianDateTime::digits(number_format($bytes/1048576,1,'.',',')).' مگابایت';if($bytes>=1024)return PersianDateTime::digits(number_format($bytes/1024,0,'.',',')).' کیلوبایت';return PersianDateTime::digits((string)$bytes).' بایت';}
    private function option(string$value,string$label,string$current):string{return'<option value="'.Renderer::e($value).'"'.($value===$current?' selected':'').'>'.Renderer::e($label).'</option>';}
    private function eventLabel(string$event):string{return['document.uploaded'=>'بارگذاری مدرک','document.replaced'=>'ثبت نسخه جدید','document.reviewed'=>'بازبینی مدرک','document.archived'=>'بایگانی مدرک','document.downloaded'=>'دانلود مدرک','document.previewed'=>'پیش‌نمایش مدرک','document.downloaded_by_token'=>'دانلود با لینک امن','document.previewed_by_token'=>'پیش‌نمایش با لینک امن','document.access_token_issued'=>'صدور لینک دسترسی کوتاه‌مدت'][$event]??$event;}
    private function pagination(string$path,int$page,int$per,int$total,array$params=[]):string{$pages=max(1,(int)ceil($total/max(1,$per)));if($pages<=1)return'';$q=$params;unset($q['page']);$prev=max(1,$page-1);$next=min($pages,$page+1);$url=static function(int$p)use($path,$q){$qq=$q;$qq['page']=$p;return$path.'?'.http_build_query(array_filter($qq,static fn($v)=>$v!==''&&$v!==null));};return'<nav class="bn-pagination"><span class="bn-pagination-meta">صفحه '.Renderer::e(PersianDateTime::digits((string)$page)).' از '.Renderer::e(PersianDateTime::digits((string)$pages)).'</span><span class="bn-pagination-actions"><a class="bn-btn bn-btn--small bn-btn--secondary'.($page<=1?' is-disabled':'').'" href="'.Renderer::e($url($prev)).'">قبلی</a><a class="bn-btn bn-btn--small bn-btn--secondary'.($page>=$pages?' is-disabled':'').'" href="'.Renderer::e($url($next)).'">بعدی</a></span></nav>';}
    private function alert(string$type,string$title,string$message):string{return'<div class="bn-alert bn-alert--'.$type.'"><strong>'.Renderer::e($title).'</strong><br>'.Renderer::e($message).'</div>';}
    private function flash(string$type,string$message):void{$_SESSION['documents_flash']=['type'=>$type,'message'=>$message];}
    private function takeFlash():string{$f=$_SESSION['documents_flash']??null;unset($_SESSION['documents_flash']);return is_array($f)?$this->alert((string)($f['type']??'info'),(string)(($f['type']??'')==='success'?'عملیات انجام شد':'عملیات کامل نشد'),(string)($f['message']??'')):'';}
    private function apiMessage(HttpResponse$r):string{$m=$r->json['error']['message']??null;if(is_string($m)&&trim($m)!=='')return$m;if($r->networkError==='upload_file_unreadable')return'فایل انتخاب‌شده روی پنل قابل خواندن نیست؛ آن را دوباره انتخاب کنید.';if($r->networkError!==null)return'ارتباط با سرویس مدارک برقرار نشد.';return'درخواست با پاسخ معتبر کامل نشد.';}
    private function errorPage(string$title,HttpResponse$r):void{http_response_code($r->status>=400&&$r->status<600?$r->status:503);$content=$this->head($title,'این بخش در حال حاضر قابل نمایش نیست.').$this->alert('error','عملیات کامل نشد',$this->apiMessage($r)).'<div class="bn-form-actions"><a class="bn-btn bn-btn--primary" href="/dashboard">بازگشت به داشبورد</a></div>';echo Renderer::page($title,$content,$this->identity,'documents');}
}
